    gates={'pueblo_sol':'P01','puerto_lirios':'P01','brumaverde':'P01','piedralumbre':'P01','brasaviva':'P01','nieveclara':'P01','vigilia':'P02','rosal_eterno':'P12','jardines_eco':'P12','travesia':'P13','refugio_hilos':'P14','bastion_velo':'P15','estacion_celia':'P16','huerto_aurelia':'P17','vigia_nocturna':'P17','cantera_esmeralda':'P17','campamento_fragmentos':'P18','ambarina':'P18','iridalia':'P19'}
